_UNSET = object()


def _git(repo, *args, data=None):
    return subprocess.run(
        ["git", "-C", str(repo.root), *args], input=data, capture_output=True,
        check=True,
    ).stdout


def _oid(commit):
    return GitOid("sha1", bytes.fromhex(commit))


def _oid_json(commit):
    return {"object_format": "sha1", "hex": commit}


def _commit(repo, files, message):
    for path, source in files.items():
        destination = repo.root / path
        if source is None:
            destination.unlink()
        else:
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(source)
    _git(repo, "add", "-A")
    _git(repo, "commit", "-q", "--no-gpg-sign", "-m", message)
    return _git(repo, "rev-parse", "HEAD").decode("ascii").strip()


