def _assert_occurrence(occurrence, *, generation, commit, path, source, names, span=None):
    assert set(occurrence) >= {
        "id", "generation", "commit", "path_bytes_b64", "path", "blob",
        "object_type", "mode", "definition_id", "names", "span",
    }
