@pytest.mark.parametrize("existing_schema", [False, True], ids=["absent", "unpublished"])
def test_query_open_never_creates_or_builds_an_index(refactor_repo, monkeypatch, existing_schema):
    path = IndexStore.locate(refactor_repo["repo"])
    assert not path.exists() and not path.parent.exists()
    if existing_schema:
        with IndexStore.create(path):
            pass

    def forbidden(*args, **kwargs):
        pytest.fail("A query attempted to create or build an index")

    monkeypatch.setattr(IndexStore, "create", forbidden)
    monkeypatch.setattr(builder, "build", forbidden)
    with CommittedRepo(refactor_repo["repo"].root) as repository:
        with pytest.raises(query.QueryError) as caught:
            with query.open_index(repository):
                pytest.fail("An unpublished index was opened")
        assert caught.value.code == "not_built"
    assert path.exists() is existing_schema
    assert path.parent.exists() is existing_schema


