def test_resolve_exact_name_locator_and_identity_use_pinned_tip(indexed, monkeypatch):
    commits = indexed["commits"]
    with _open(indexed) as session:
        live = _resolved(session)
        assert live["lifecycle"] == "present" and live["historical_only"] is False
        for token in ("security.py::check_token", live["eid"], live["eid"][:13]):
            assert _resolved(session, token) == live
        for token in ("check", "Check_token", "auth.py::check_token", "validate_token"):
            _assert_page(session.resolve(token), total=0, status="not_found")
        original = _resolved(session, "auth.py::validate_token", at=_oid(commits[0]))
        assert original["eid"] == live["eid"]
        assert original["occurrence"]["commit"] == _oid_json(commits[0])

        calls = []
        resolve = CommittedRepo.resolve

        def recording(repository, revision):
            calls.append(revision)
            return resolve(repository, revision)

        monkeypatch.setattr(CommittedRepo, "resolve", recording)
        _git(indexed["repo"], "update-ref", "refs/heads/main", commits[0])
        assert _resolved(session) == live
        assert calls == []
        assert _resolved(session, "validate_token", at="HEAD")["eid"] == live["eid"]
        assert calls == ["HEAD"]


