def test_reused_retired_name_returns_separate_current_and_historical_lineages(tmp_path):
    source = b"def tracked(raw):\n    return raw.strip() + '!'\n"
    fixture = _timeline(tmp_path / "reused", (
        {"tracked.py": source}, {"tracked.py": None}, {"tracked.py": source},
    ))
    with _open(fixture) as session:
        current = _resolved(session, "tracked")
        genesis = _resolved(session, "tracked", at=_oid(fixture["commits"][0]))
        assert current["eid"] != genesis["eid"]
        result = session.resolve("tracked", historical=True, limit=1)
        _assert_page(result, total=2, status="ambiguous")
        rows = _assert_page(session.resolve("tracked", historical=True), total=2, status="ambiguous")
        by_eid = {row["eid"]: row for row in rows}
        assert set(by_eid) == {current["eid"], genesis["eid"]}
        assert by_eid[current["eid"]]["historical_only"] is False
        retired = by_eid[genesis["eid"]]
        assert retired["historical_only"] is True and retired["lifecycle"] == "removed"
        assert retired["occurrence"] is None
        assert retired["last_known_occurrence"]["commit"] == _oid_json(fixture["commits"][0])
        assert _resolved(session, genesis["eid"][:13])["eid"] == genesis["eid"]


def test_state_distinguishes_absent_removed_and_unknown_before_observed_seed(lifecycle_index):
    fixture = lifecycle_index
    commits = tuple(_oid(commit) for commit in fixture["commits"])
    with _open(fixture) as session:
        genesis = _resolved(session, "tracked", at=commits[1])["eid"]
        recovered = _resolved(session, "tracked", at=commits[3])["eid"]
        assert genesis.startswith("eid1_") and recovered.startswith("oeid1_")
        for identity, position, expected, last in (
            (genesis, 0, "absent", None), (genesis, 1, "present", None),
            (genesis, 2, "unknown", 1), (genesis, 5, "unknown", 1),
            (recovered, 0, "unknown", None), (recovered, 2, "unknown", None),
            (recovered, 3, "present", None), (recovered, 4, "removed", 3),
            (recovered, 5, "removed", 3),
        ):
            state = session.state_at(identity, commits[position])
            assert json.loads(json.dumps(state)) == state
            assert set(state) >= {"eid", "state", "occurrence", "reason", "last_known_occurrence"}
            assert state["eid"] == identity and state["state"] == expected
            if expected == "present":
                assert state["occurrence"]["commit"] == _oid_json(fixture["commits"][position])
            else:
                assert state["occurrence"] is None
                if last is None:
                    assert state["last_known_occurrence"] is None
            if last is not None:
                assert state["last_known_occurrence"]["commit"] == _oid_json(fixture["commits"][last])
            if expected == "unknown":
                assert type(state["reason"]) is str and state["reason"]
        assert session.state_at(recovered) == session.state_at(recovered, commits[-1])
        retired_observation = _resolved(session, recovered[:14])
        assert retired_observation["eid"] == recovered
        assert retired_observation["lifecycle"] == "removed"
        for position, status, total in ((0, "absent", 0), (2, "unknown", None), (4, "removed", 0)):
            page = session.entities_in(b"tracked.py", commits[position])
            assert _assert_page(page, status=status, total=total) == []
            assert page["coverage"]


def test_identity_and_commit_must_belong_to_selected_context_and_generation(indexed):
    with _open(indexed) as original:
        old_eid = _resolved(original)["eid"]
    bounded = _build(indexed, since=indexed["commits"][2], rebuild=True)
    with _open(indexed) as current:
        assert current.context == bounded.context
        assert current.context != indexed["built"].context
        eid = _resolved(current)["eid"]
        assert eid.startswith("oeid1_")
        _assert_error("identity_outside_scope", current.state_at, old_eid)
        _assert_error("identity_outside_scope", current.history, old_eid)
        outside = _oid(indexed["commits"][0])
        _assert_error("outside_scope", current.state_at, eid, outside)
        _assert_error("outside_scope", current.resolve, "check_token", at=outside)
        _assert_error("outside_scope", current.history, eid, at=outside)
        _assert_error("outside_scope", current.entities_in, b"auth.py", outside)
        _assert_error("outside_scope", current.events_in, outside, current.tip)
    with _open(indexed, generation=indexed["built"].generation) as retained:
        assert _resolved(retained)["eid"] == old_eid


def test_state_uses_active_file_interval_not_last_event_and_does_not_persist_occurrence(indexed):
    prefix = b"# Coordinates move without a function edit.\n\n"
    source = prefix + indexed["sources"][-1]
    shifted = _commit(indexed["repo"], {"security.py": source}, "Shift function coordinates")
    untouched = _commit(indexed["repo"], {"notes.txt": b"A different file changed.\n"}, "Leave function untouched")
    built = _build(indexed)
    with _open(indexed) as session, IndexStore.open(IndexStore.locate(indexed["repo"])) as store:
        eid = _resolved(session)["eid"]
        events = _assert_page(session.history(eid, order="oldest"), total=5)
        assert events[-1]["commit"] == _oid_json(indexed["commits"][-1])
        occurrences = []
        for commit in (shifted, untouched):
            state = session.state_at(eid, _oid(commit))
            assert state["state"] == "present"
            occurrence = state["occurrence"]
            _assert_occurrence(
                occurrence, generation=built.generation, commit=commit, path=b"security.py",
                source=source, names=["check_token"],
                span={"start_byte": len(prefix), "end_byte": len(source) - 1,
                      "start_line": 3, "end_line": source.count(b"\n")},
            )
            occurrences.append(occurrence)
        assert occurrences[0]["id"] != occurrences[1]["id"]
        synthesized = occurrences[-1]
        assert store.connection.execute("SELECT 1 FROM occurrence WHERE id = ?", (synthesized["id"],)).fetchone() is None
        assert session.source(synthesized) == indexed["sources"][-1][:-1]
        assert store.connection.execute("SELECT 1 FROM occurrence WHERE id = ?", (synthesized["id"],)).fetchone() is None


@pytest.mark.parametrize("order", ["oldest", "newest"])
def test_history_five_real_events_have_exact_edges_occurrences_and_full_ids(indexed, order):
    with _open(indexed) as session:
        eid = _resolved(session)["eid"]
        rows = _assert_page(session.history(eid, order=order), total=5)
        steps = list(range(5)) if order == "oldest" else list(reversed(range(5)))
        flags = ("added", "body_changed", "renamed", "moved", "body_changed")
        for event, step in zip(rows, steps, strict=True):
            _assert_id(event["id"], "evt1")
            assert event["eid"] == eid and event["material"] is True
            assert isinstance(event["flags"], list) and flags[step] in event["flags"]
            assert event["commit"] == _oid_json(indexed["commits"][step])
            assert event["parent"] == (_oid_json(indexed["commits"][step - 1]) if step else None)
            for endpoint, position in (("source", step - 1), ("destination", step)):
                if position < 0:
                    assert event[endpoint] is None
                else:
                    _assert_occurrence(
                        event[endpoint], generation=session.generation,
                        commit=indexed["commits"][position], path=indexed["paths"][position].encode("ascii"),
                        source=indexed["sources"][position], names=[indexed["names"][position]],
                    )
                    assert session.source(event[endpoint]) == indexed["sources"][position][:-1]
            if event.get("decision") is not None:
                assert set(event["decision"]) >= {"status", "reason", "evidence"}
                assert event["decision"]["status"] == "accepted"
                assert event["decision"]["reason"] and event["decision"]["evidence"]


def test_history_cutoff_is_inclusive_and_pages_cannot_leak_later_events(indexed):
    cutoff = _oid(indexed["commits"][2])
    with _open(indexed) as session:
        eid = _resolved(session)["eid"]
        first = session.history(eid, at=cutoff, order="oldest", limit=2)
        rows = _assert_page(first, total=3)
        second = session.history(eid, at=cutoff, order="oldest", limit=2, cursor=first["page"]["next_cursor"])
        rows += _assert_page(second, total=3)
        assert [event["commit"] for event in rows] == [_oid_json(commit) for commit in indexed["commits"][:3]]
        assert second["page"]["next_cursor"] is None


def test_entities_page_contains_only_active_file_and_uses_stable_byte_order(indexed):
    path = b"security.py"
    with _open(indexed) as session, IndexStore.open(IndexStore.locate(indexed["repo"])) as store:
        whole = session.entities_in(path, session.tip, limit=1000)
        expected = _assert_page(whole)
        assert 0 < len(expected) <= 1000
        kinds = dict(store.connection.execute("SELECT id, kind FROM definition"))
        keys = [(b64decode(row["path_bytes_b64"]), row["span"]["start_byte"],
                 kinds[row["definition_id"]], row["id"]) for row in expected]
        assert keys == sorted(keys)
        assert all(row["path_bytes_b64"] == b64encode(path).decode("ascii") for row in expected)
        assert all(row["commit"] == _oid_json(indexed["commits"][-1]) for row in expected)
        cursor, gathered = None, []
        for unused in range(len(expected) + 1):
            page = session.entities_in(path, session.tip, cursor=cursor, limit=1)
            gathered.extend(_assert_page(page, total=len(expected)))
            cursor = page["page"]["next_cursor"]
            if cursor is None:
                break
        else:
            pytest.fail("Entity cursor failed to terminate")
        assert gathered == expected
        assert all(row["names"] != ["check_token"] for row in session.entities_in(b"auth.py")["results"])


