def test_source_rejects_every_tampered_reference_field_and_self_consistent_wrong_state(indexed):
    with _open(indexed) as session:
        valid = _resolved(session)["occurrence"]
        corruptions = {
            "id": "occ1_" + "0" * 64, "generation": session.generation + "-other",
            "commit": _oid_json(indexed["commits"][0]),
            "path_bytes_b64": b64encode(b"auth.py").decode("ascii"),
            "path": "auth.py", "blob": _oid_json("0" * 40),
            "object_type": "tree", "mode": 0o100755,
            "definition_id": "def1_" + "0" * 64, "names": ["forged_name"],
        }
        invalid = []
        for field, value in corruptions.items():
            altered = deepcopy(valid)
            altered[field] = value
            invalid.append((field, altered))
        for field in ("start_byte", "end_byte", "start_line", "end_line"):
            altered = deepcopy(valid)
            altered["span"][field] += 1
            invalid.append((field, altered))
        for field in ("id", "generation", "commit", "path_bytes_b64", "blob", "object_type", "mode", "definition_id", "span"):
            altered = deepcopy(valid)
            del altered[field]
            invalid.append((f"missing {field}", altered))
        forged = deepcopy(valid)
        forged["path"] = "auth.py"
        forged["path_bytes_b64"] = b64encode(b"auth.py").decode("ascii")
        forged["id"] = EntityOccurrence(
            session.tip, b"auth.py", _oid(valid["blob"]["hex"]), "blob", valid["mode"], valid["definition_id"],
        ).id
        invalid.extend((("self-consistent wrong file", forged), ("opaque ID only", "occ1_" + "0" * 64)))
        for label, altered in invalid:
            with pytest.raises(query.QueryError) as caught:
                session.source(altered)
            assert caught.value.code in {"invalid_source", "source_unavailable"}, label
        assert session.source(valid) == indexed["sources"][-1][:-1]


def test_raw_case_tab_newline_and_invalid_utf8_paths_round_trip_without_display_loss(tmp_path):
    repo = _init_repo(tmp_path / "raw-paths")
    sources = {
        path: f"def item_{number}(raw):\n    return raw + {number + 11}\n".encode("ascii")
        for number, path in enumerate((b"Case.py", b"case.py", b"tab\tline\n.py", b"bad-\xff.py"))
    }
    entries = []
    for path, source in sorted(sources.items()):
        blob = _git(repo, "hash-object", "-w", "--stdin", data=source).strip()
        entries.append(b"100644 blob " + blob + b"\t" + path + b"\0")
    tree = _git(repo, "mktree", "-z", data=b"".join(entries)).decode("ascii").strip()
    commit = _git(repo, "commit-tree", tree, "-m", "Literal byte paths").decode("ascii").strip()
    _git(repo, "update-ref", "refs/heads/main", commit)
    fixture = {"repo": repo}
    built = _build(fixture)
    with _open(fixture) as session:
        seen = []
        for number, (path, source) in enumerate(sources.items()):
            rows = _assert_page(session.entities_in(path))
            assert rows and all(b64decode(row["path_bytes_b64"]) == path for row in rows)
            matches = [row for row in rows if row["names"] == [f"item_{number}"]]
            assert len(matches) == 1
            occurrence = matches[0]
            _assert_occurrence(occurrence, generation=built.generation, commit=commit,
                               path=path, source=source, names=[f"item_{number}"])
            assert session.source(occurrence) == source[:-1]
            seen.append(occurrence["id"])
        assert len(set(seen)) == len(sources)
        _assert_page(session.entities_in(b"CASE.py"), status="absent", total=0)


def test_all_queries_are_readonly_and_do_not_walk_or_read_git_objects(indexed, monkeypatch):
    writes, opened = [], []
    write_codes = {getattr(sqlite3, name) for name in (
        "SQLITE_INSERT", "SQLITE_UPDATE", "SQLITE_DELETE", "SQLITE_ALTER_TABLE",
        "SQLITE_CREATE_INDEX", "SQLITE_CREATE_TABLE", "SQLITE_CREATE_TRIGGER", "SQLITE_CREATE_VIEW",
        "SQLITE_CREATE_TEMP_INDEX", "SQLITE_CREATE_TEMP_TABLE", "SQLITE_CREATE_TEMP_TRIGGER", "SQLITE_CREATE_TEMP_VIEW",
        "SQLITE_DROP_INDEX", "SQLITE_DROP_TABLE", "SQLITE_DROP_TRIGGER", "SQLITE_DROP_VIEW",
        "SQLITE_DROP_TEMP_INDEX", "SQLITE_DROP_TEMP_TABLE", "SQLITE_DROP_TEMP_TRIGGER", "SQLITE_DROP_TEMP_VIEW",
    )}
    original_open = IndexStore.open.__func__

    def recording(cls, *args, **kwargs):
        store = original_open(cls, *args, **kwargs)
        opened.append(store)

        def authorize(action, first, second, database, trigger):
            if action in write_codes:
                writes.append((action, first, second))
                return sqlite3.SQLITE_DENY
            return store._authorize(action, first, second, database, trigger)

        store.connection.set_authorizer(authorize)
        return store

    def forbidden(*args, **kwargs):
        pytest.fail("An indexed query invoked a build, history walk, or object read")

    def metadata_only(original):
        def run(repository, *args, **kwargs):
            if args[:1] == ("rev-parse",) and "--git-common-dir" in args:
                return original(repository, *args, **kwargs)
            forbidden(*args, **kwargs)
        return run

    monkeypatch.setattr(IndexStore, "open", classmethod(recording))
    monkeypatch.setattr(builder, "build", forbidden)
    with CommittedRepo(indexed["repo"].root) as repository, ExitStack() as stack:
        with monkeypatch.context() as guard:
            guard.setattr(CommittedRepo, "_run", metadata_only(CommittedRepo._run))
            guard.setattr(Repo, "_run", metadata_only(Repo._run))
            for name in ("resolve", "commit", "iter_tree", "read_object", "object_info"):
                guard.setattr(CommittedRepo, name, forbidden)
            guard.setattr(Repo, "walk", forbidden)
            guard.setattr(evidence, "parse_evidence", forbidden)
            session = stack.enter_context(query.open_index(repository))
            eid = _resolved(session)["eid"]
            occurrence = session.state_at(eid, session.tip)["occurrence"]
            _assert_page(session.resolve("validate_token", historical=True))
            _assert_page(session.history(eid))
            _assert_page(session.entities_in(b"security.py", session.tip))
            _assert_page(session.events_in(_oid(indexed["commits"][0]), session.tip))
        assert session.source(occurrence) == indexed["sources"][-1][:-1]
        assert opened and all(store.read_only for store in opened)
        assert writes == []


def _cursor_fields(cursor):
    return json.loads(urlsafe_b64decode(cursor + "=" * (-len(cursor) % 4)))


def _cursor(fields):
    payload = json.dumps(fields, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return urlsafe_b64encode(payload).decode("ascii").rstrip("=")


@pytest.mark.parametrize("malformation", ["oversized", "base64", "json", "version"])
def test_cursor_validation_is_bounded_strict_and_typed(indexed, monkeypatch, malformation):
    with _open(indexed) as session:
        eid = _resolved(session)["eid"]
        token = session.history(eid, limit=1)["page"]["next_cursor"]
        fields = _cursor_fields(token)
        assert isinstance(fields, dict)
        assert _cursor(fields) == token.rstrip("=")
        if malformation == "oversized":
            token = "a" * 4097
            decoders = (base64.b64decode, base64.urlsafe_b64decode)

            def forbidden(*args, **kwargs):
                pytest.fail("Oversized cursor reached base64 decoding")

            for name, value in tuple(vars(query).items()):
                if any(value is decoder for decoder in decoders):
                    monkeypatch.setattr(query, name, forbidden)
            monkeypatch.setattr(base64, "b64decode", forbidden)
            monkeypatch.setattr(base64, "urlsafe_b64decode", forbidden)
        elif malformation == "base64":
            token = "%%%not-base64%%%"
        elif malformation == "json":
            token = urlsafe_b64encode(b"{").decode("ascii").rstrip("=")
        else:
            fields["version"] = 9999
            token = _cursor(fields)
        _assert_error("invalid_cursor", session.history, eid, cursor=token, limit=1)


def test_cursor_binds_action_scope_identity_revision_order_and_exact_filter(indexed):
    with _open(indexed) as session:
        eid = _resolved(session)["eid"]
        first = session.history(eid, order="oldest", limit=1)
        token = first["page"]["next_cursor"]
        other = next(row["eid"] for row in session.events_in(
            _oid(indexed["commits"][0]), session.tip,
        )["results"] if row["eid"] != eid)
        for operation, args, options in (
            (session.history, (eid,), {"order": "newest"}),
            (session.history, (eid,), {"order": "oldest", "at": _oid(indexed["commits"][3])}),
            (session.history, (other,), {"order": "oldest"}),
            (session.resolve, ("check_token",), {}),
            (session.entities_in, (b"security.py",), {}),
            (session.events_in, (_oid(indexed["commits"][0]), session.tip), {}),
        ):
            _assert_error("invalid_cursor", operation, *args, cursor=token, **options)
        fields = _cursor_fields(token)
        for field in ("unexpected", "scope", "context", "generation", "last"):
            invalid = {**fields, field: {"not": "a valid cursor field"}}
            _assert_error("invalid_cursor", session.history, eid, cursor=_cursor(invalid), order="oldest")
        incomplete = dict(fields)
        del incomplete[next(iter(incomplete))]
        _assert_error("invalid_cursor", session.history, eid, cursor=_cursor(incomplete), order="oldest")
        noncanonical = urlsafe_b64encode(json.dumps(fields, indent=2).encode("utf-8")).decode("ascii").rstrip("=")
        _assert_error("invalid_cursor", session.history, eid, cursor=noncanonical, order="oldest")
        entity_cursor = session.entities_in(b"security.py", limit=1)["page"]["next_cursor"]
        assert entity_cursor is not None
        _assert_error("invalid_cursor", session.entities_in, b"auth.py", cursor=entity_cursor)
        range_cursor = session.events_in(_oid(indexed["commits"][0]), session.tip, limit=1)["page"]["next_cursor"]
        _assert_error("invalid_cursor", session.events_in, _oid(indexed["commits"][1]), session.tip, cursor=range_cursor)
    _build(indexed, scope="cursor-other")
    with _open(indexed, scope="cursor-other") as other_scope:
        _assert_error("invalid_cursor", other_scope.history, eid, cursor=token, order="oldest")


def _gather(operation, *args, **options):
    cursor, gathered, seen = None, [], set()
    for unused in range(64):
        result = operation(*args, **options, cursor=cursor, limit=1)
        gathered.extend(_assert_page(result))
        cursor = result["page"]["next_cursor"]
        if cursor is None:
            return gathered
        assert cursor not in seen
        seen.add(cursor)
    pytest.fail("Cursor did not terminate for the bounded fixture")


def test_keyset_pages_are_complete_without_duplicates_in_both_history_orders_and_tied_events(indexed):
    positions = {commit: number for number, commit in enumerate(indexed["commits"])}
    with _open(indexed) as session:
        eid = _resolved(session)["eid"]
        for order in ("oldest", "newest"):
            expected = _assert_page(session.history(eid, order=order), total=5)
            actual = _gather(session.history, eid, order=order)
            assert actual == expected
            assert len({row["id"] for row in actual}) == 5
            keys = [(positions[row["commit"]["hex"]], row["id"]) for row in actual]
            assert keys == sorted(keys, reverse=order == "newest")
        assert session.history(eid)["results"] == session.history(eid, order="newest")["results"]
        base = _oid(indexed["commits"][0])
        expected = _assert_page(session.events_in(base, session.tip, limit=1000))
        actual = _gather(session.events_in, base, session.tip)
        assert actual == expected
        assert len({row["commit"]["hex"] for row in actual}) < len(actual)
        keys = [(positions[row["commit"]["hex"]], row["id"]) for row in actual]
        assert keys == sorted(set(keys))


@pytest.mark.parametrize("context", ["same", "bounded"])
def test_old_session_and_explicit_generation_resume_cursor_after_publication(indexed, context):
    with _open(indexed) as held:
        eid = _resolved(held)["eid"]
        old_source = _resolved(held)["occurrence"]
        first = held.history(eid, order="oldest", limit=2)
        cursor = first["page"]["next_cursor"]
        expected = held.history(eid, order="oldest")["results"][2:]
        new_source = indexed["sources"][-1].replace(b"return len(parts)", b"return bool(raw) and len(parts)")
        new_tip = _commit(indexed["repo"], {"security.py": new_source}, "Advance published generation")
        options = {"since": indexed["commits"][2]} if context == "bounded" else {}
        published = _build(indexed, rebuild=True, **options)
        assert published.generation != held.generation
        assert (published.context == held.context) is (context == "same")
        assert held.tip == _oid(indexed["commits"][-1])
        resumed = held.history(eid, order="oldest", cursor=cursor)
        assert _assert_page(resumed, total=5) == expected
        with _open(indexed, generation=held.generation) as reopened:
            assert reopened.generation == held.generation
            assert reopened.history(eid, order="oldest", cursor=cursor)["results"] == expected
            assert reopened.source(old_source) == indexed["sources"][-1][:-1]
        with _open(indexed) as current:
            assert current.generation == published.generation
            assert current.tip == _oid(new_tip)
            current_eid = _resolved(current)["eid"]
            _assert_error("invalid_cursor", current.history, current_eid, order="oldest", cursor=cursor)
            with pytest.raises(query.QueryError) as caught:
                current.source(old_source)
            assert caught.value.code in {"invalid_source", "source_unavailable"}


def test_collected_generation_is_gone_on_reopen_but_held_wal_reader_can_finish(indexed):
    with _open(indexed) as held:
        eid = _resolved(held)["eid"]
        first = held.history(eid, order="oldest", limit=2)
        expected = held.history(eid, order="oldest")["results"][2:]
        published = _build(indexed, rebuild=True)
        assert published.generation != held.generation
        with IndexStore.open(IndexStore.locate(indexed["repo"]), read_only=False) as writer:
            with writer.transaction():
                writer.collect_generation(held.generation)
        result = held.history(eid, order="oldest", cursor=first["page"]["next_cursor"])
        assert _assert_page(result, total=5) == expected
        assert held.source(expected[-1]["destination"]) == indexed["sources"][-1][:-1]
        with pytest.raises(query.QueryError) as caught:
            with _open(indexed, generation=held.generation):
                pytest.fail("A collected generation was reopened")
        assert caught.value.code == "generation_gone"


