def test_warm_full_identity_lookup_cost_is_bounded_by_selected_identity(tmp_path):
    costs = []
    for unrelated_count in (0, 300):
        files = {"target.py": b"def target():\n    return 123\n"}
        if unrelated_count:
            files["unrelated.py"] = b"\n".join(
                f"def unrelated_{number}():\n    return {number}\n".encode("ascii")
                for number in range(unrelated_count)
            )
        fixture = _timeline(tmp_path / f"population-{unrelated_count}", (files,))
        with _open(fixture) as session:
            if unrelated_count:
                rows = _assert_page(session.entities_in(b"unrelated.py", limit=1000))
                names = {tuple(row["names"]) for row in rows}
                assert {(f"unrelated_{number}",) for number in range(unrelated_count)} <= names
            expected = _resolved(session, "target.py::target")
            assert _resolved(session, expected["eid"]) == expected
            steps = 0

            def count_step():
                nonlocal steps
                steps += 1
                return 0

            connection = session._store.connection
            connection.set_progress_handler(count_step, 1)
            try:
                actual = _resolved(session, expected["eid"])
            finally:
                connection.set_progress_handler(None, 0)
            assert actual == expected
            assert steps > 0
            costs.append(steps)
    baseline, expanded = costs
    assert expanded <= baseline * 2 + 2000, {"baseline": baseline, "expanded": expanded}


def _coverage_of(fixture, name):
    with _open(fixture) as session:
        return session.resolve(name)["coverage"]


def test_an_unsupported_file_is_excluded_coverage_not_a_continuity_gap(tmp_path):
    """A LICENSE has no grammar and never will.

    Counting it as a gap warned that an entity might be reported as removed and
    added when nothing of the kind could happen, and sent the reader to a
    rebuild that could not improve. It is still *uncovered* -- the index really
    does not cover that file -- which is a different question and stays visible.
    """
    source = (b"def handle(raw):\n    return raw\n",
              b"def handle(raw):\n    return raw.strip()\n")
    fixture = _timeline(tmp_path / "excluded", (
        {"app.py": source[0], "NOTICE.txt": b"free text, no grammar\n"},
        {"app.py": source[1], "NOTICE.txt": b"free text, no grammar\n"},
    ))

    coverage = _coverage_of(fixture, "handle")
    assert coverage["gaps"] == 0, "an exclusion cannot orphan a lineage"
    assert coverage["excluded"] > 0, "the unsupported file must stay on the record"
    assert coverage["uncovered"] >= coverage["excluded"]
    assert coverage["status"] == "partial", "the tree is still not fully indexed"


def test_a_parse_error_is_a_real_continuity_gap(tmp_path):
    """The case the warning exists for: evidence that is genuinely missing.

    The counterpart to the test above -- without it, reporting zero gaps for
    everything would pass just as well.
    """
    fixture = _timeline(tmp_path / "broken", (
        {"app.py": b"def handle(raw):\n    return raw\n", "broken.py": b"def broken(:\n"},
        {"app.py": b"def handle(raw):\n    return raw.strip()\n", "broken.py": b"def broken(:\n"},
    ))

    coverage = _coverage_of(fixture, "handle")
    assert coverage["gaps"] > 0, "a parse error is exactly what a gap means"
    assert coverage["status"] == "partial"


def test_generation_coverage_aggregate_is_reused_across_pages_and_methods(indexed):
    statements = []
    with _open(indexed) as session:
        connection = session._store.connection
        connection.set_trace_callback(statements.append)
        try:
            first = session.resolve("check_token")
            eid = _assert_page(first, total=1, status="unique")[0]["eid"]
            expected_coverage = deepcopy(first["coverage"])
            assert expected_coverage["records"] > 0
            history = session.history(eid, order="oldest", limit=1)
            first_event = _assert_page(history, total=5)[0]
            assert history["coverage"] == expected_coverage
            cursor = history["page"]["next_cursor"]
            assert cursor is not None
            resumed = session.history(eid, order="oldest", limit=1, cursor=cursor)
            second_event = _assert_page(resumed, total=5)[0]
            assert first_event["commit"] == _oid_json(indexed["commits"][0])
            assert second_event["commit"] == _oid_json(indexed["commits"][1])
            assert resumed["coverage"] == expected_coverage
            for page in (
                session.resolve(eid),
                session.entities_in(b"security.py"),
                session.events_in(_oid(indexed["commits"][0]), session.tip, limit=1),
            ):
                _assert_page(page)
                assert page["coverage"] == expected_coverage
        finally:
            connection.set_trace_callback(None)
    aggregates = [statement for statement in statements
                  if re.search(r"\bFROM\s+coverage\b", statement, re.IGNORECASE)
                  and re.search(r"\b(?:COUNT|SUM)\s*\(", statement, re.IGNORECASE)]
    assert len(aggregates) <= 1, aggregates


