class TestF3CheckpointHarness:
    def test_runner_uses_real_cli_and_retains_five_event_fixture(self, f3_manual, tmp_path, monkeypatch):
        calls = []
        original = f3_manual.subprocess.run

        def recording(command, *args, **kwargs):
            completed = original(command, *args, **kwargs)
            if list(command)[1:3] == ["-m", "gita"]:
                calls.append((list(command), kwargs, completed))
            return completed

        monkeypatch.setattr(f3_manual.subprocess, "run", recording)
        results = f3_manual.check_f3()

        assert len(results) >= 5
        assert all(result.verdict == f3_manual.PASS for result in results), results
        assert len(calls) >= 6
        payloads = []
        for command, options, completed in calls:
            assert command[:3] == [sys.executable, "-m", "gita"]
            assert "-C" in command
            assert Path(options["cwd"]).resolve() == f3_manual.ROOT.resolve()
            if completed.returncode == 0:
                payload = json.loads(completed.stdout)
                assert isinstance(payload, dict)
                assert {"command", "status", "results"} <= payload.keys()
                payloads.append((command, payload))

        histories = [payload for _, payload in payloads if payload["command"] == "history"]
        assert {3, 5} <= {payload["page"]["total"] for payload in histories}
        assert len({row["commit"]["hex"] for payload in histories for row in payload["results"]}) == 5
        identities = [(command, payload) for command, payload in payloads if payload["command"] == "id"]
        assert any("--historical" in command for command, _ in identities)
        assert len({row["eid"] for _, payload in identities for row in payload["results"]}) == 1
        assert any("--cursor" in command and "--generation" in command for command, _, _ in calls)
        assert any(completed.returncode == 6 and completed.stdout == ""
                   for _, _, completed in calls)
        verification = [completed for command, _, completed in calls if "--verify" in command]
        assert verification and all(completed.returncode == 3 for completed in verification)
        assert all(json.loads(completed.stdout)["status"] == "unverified" for completed in verification)
        missing = [(command, payload) for command, payload in payloads
                   if payload["status"] == "not_built"]
        assert missing
        for command, _ in missing:
            repository = Repo(Path(command[command.index("-C") + 1]))
            assert not IndexStore.locate(repository).parent.exists()

        retained = list(tmp_path.glob("gita-verify-indexed-*"))
        assert len(retained) == 1 and retained[0].is_dir()
        assert any(path.is_dir() for path in retained[0].rglob(".git"))
        assert any(path.is_file() for path in retained[0].rglob("*.sqlite*"))

    def test_stage_main_reports_f3_without_claiming_f4_complete(self, f3_manual, monkeypatch, capsys):
        monkeypatch.setattr(sys, "argv", [str(f3_manual.__file__), "--stage", "f3"])

        assert f3_manual.main() == 0

        output = capsys.readouterr().out
        assert re.search(r"(?m)^F3\s+.*CHECKPOINT", output)
        assert output.count("PASS") >= 5
        assert "FAIL" not in output
        assert not re.search(r"(?im)^F4\b.*(?:PASS|COMPLETE|CHECKPOINT)", output)

    @pytest.mark.parametrize(
        ("returncode", "stdout", "stderr"),
        [(0, "{}", ""), (4, "", "io error")],
        ids=["invalid-json-envelope-zero-exit", "nonzero-io-error"],
    )
    def test_bad_cli_results_fail_runner_and_main(
        self, f3_manual, monkeypatch, capsys, returncode, stdout, stderr,
    ):
        original = f3_manual.subprocess.run
        intercepted = []

        def broken_cli(command, *args, **kwargs):
            if list(command)[1:3] == ["-m", "gita"]:
                intercepted.append(list(command))
                return subprocess.CompletedProcess(command, returncode, stdout=stdout, stderr=stderr)
            return original(command, *args, **kwargs)

        monkeypatch.setattr(f3_manual.subprocess, "run", broken_cli)
        results = f3_manual.check_f3()
        assert intercepted
        assert results and any(result.verdict == f3_manual.FAIL for result in results), results
        assert not all(result.verdict == f3_manual.PASS for result in results)
        previous_calls = len(intercepted)
        monkeypatch.setattr(sys, "argv", [str(f3_manual.__file__), "--stage", "f3"])

        assert f3_manual.main() == 1

        assert len(intercepted) > previous_calls
        output = capsys.readouterr().out
        assert "F3" in output and "FAIL" in output
        assert "Completed registered checkpoint checks passed." not in output

